public static InventSum findInventSum(str _barcodeScanned)
{
    InventSerial    inventSerial;
    InventBatch     inventBatch;
    InventSum       inventSum;
    InventDim       inventDim;

    InventBatchId   inventBatchId;
    InventSerialId  inventSerialId;
    inventBatchId = _barcodeScanned;
    inventSerialId = _barcodeScanned;

    select firstonly inventSum where inventSum.AvailPhysical > 0
        join inventDim
        where (InventDim.inventBatchId == inventBatchId || InventDim.inventSerialId == inventSerialId)
        && inventDim.inventDimId == inventSum.InventDimId;

    return inventSum;
}
